# Check if 2s fill gaps between adjacent 3s (horizontally or vertically)
def get_neighbors(r, c, rows, cols):
    """Get all adjacent cells (up, down, left, right)"""
    neigh = []
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            neigh.append((nr, nc))
    return neigh

def has_3_neighbor(r, c, grid):
    """Check if cell (r,c) has any neighbor that contains 3"""
    rows = len(grid)
    cols = len(grid[0])
    for nr, nc in get_neighbors(r, c, rows, cols):
        if grid[nr][nc] == 3:
            return True
    return False

def has_3_neighbor_in_output(output_grid):
    """Check if output has a 3 at neighbor position"""
    rows = len(output_grid)
    cols = len(output_grid[0])
    for nr, nc in get_neighbors(r, c, rows, cols):
        if output_grid[nr][nc] == 3:
            return True
    return False

# Let's test my hypothesis: A cell becomes 2 if it was 9 in input AND 
# has two 3 neighbors (forming a bridge)

print("Testing bridge hypothesis...")
for r in range(len(inp)):
    for c in range(len(inp[0])):
        # Check if inp[r][c] == 9 and out[r][c] == 2
        if inp[r][c] == 9 and out[r][c] == 2:
            # Count how many 3s are adjacent to it
            neighbors_with_3 = sum(1 for nr, nc in get_neighbors(r, c, len(inp), len(inp[0])) 
                                   if inp[nr][nc] == 3)
            print(f"({r},{c}): 2 neighbors, {neighbors_with_3} have 3", end="")

            # Also count diagonals
            diag_neighbors_with_3 = sum(1 for nr, nc in [(r+dr, c+dc) for dr, dc in [(-1,-1), (-1,1), (1,-1), (1,1)]]
                                       if 0 <= nr < len(inp) and 0 <= nc < len(inp[0]) and inp[nr][nc] == 3)
            print(f" -> diagonal 3s: {diag_neighbors_with_3}")

def check_bridge_rule(inp, out):
    """Check if the rule is: fill gaps between 3s by making 9->2 when exactly 2 adjacent are 3"""
    rows = len(inp)
    cols = len(inp[0])

    # First check all 2s - they should be at positions with exactly 2 3-neighbors
    for r in range(rows):
        for c in range(cols):
            if out[r][c] == 2:
                count = sum(1 for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)] 
                           if 0 <= r+dr < rows and 0 <= c+dc < cols and inp[r+dr][c+dc] == 3)
                if count != 2:
                    print(f"ERROR: ({r},{c}) should be 2 but has {count} 3-neighbors")
                    return False

    # Check that no non-2 positions satisfy the bridge condition
    for r in range(rows):
        for c in range(cols):
            if inp[r][c] == 9 and out[r][c] != 2:
                count = sum(1 for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)] 
                           if 0 <= r+dr < rows and 0 <= c+dc < cols and inp[r+dr][c+dc] == 3)
                if count == 2:
                    print(f"ERROR: ({r},{c}) has 2 3-neighbors but stays {out[r][c]}")
                    return False

    return True

if check_bridge_rule(inp, out):
    print("Bridge rule VERIFIED!")

