def apply_horizontal_only_rule(grid):
    rows = len(grid)
    cols = len(grid[0])

    result = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if result[r][c] == 9:  # Only change background
                left_is_3 = 0 <= c-1 < cols and result[r][c-1] == 3
                right_is_3 = 0 <= c+1 < cols and result[r][c+1] == 3

                if left_is_3 and right_is_3:
                    result[r][c] = 2

    return result

result = apply_horizontal_only_rule(inp)

